+
+/* -------------------------------------------------------------------------- */
+/*  Edit (remind update, MCP remind_update)                                   */
+/* -------------------------------------------------------------------------- */
+
+/**
+ * An edit to ONE reminder. Every field is optional; `dueAt: null` clears the
+ * due date. `status: 'done'` is the same flip as `remind done`, `'pending'`
+ * reopens a done reminder.
+ */
+export interface ReminderPatch {
+  text?: string;
+  dueAt?: string | null;
+  priority?: ItemPriority;
+  status?: 'pending' | 'done';
+}
+
+/**
+ * Pure: the item after `patch`. Text rewrites `body` and `prompt` together
+ * (the convention of `buildReminderItem`); a done reminder that stays done
+ * keeps its original `answeredAt`.
+ */
+export function applyReminderPatch(item: ReminderItem, patch: ReminderPatch, now: string): ReminderItem {
+  const next: ReminderItem = { ...item };
+  if (patch.text !== undefined) {
+    const text = patch.text.trim();
+    next.body = text;
+    next.prompt = text;
+  }
+  if (patch.dueAt === null) delete next.dueAt;
+  else if (patch.dueAt !== undefined) next.dueAt = new Date(patch.dueAt).toISOString();
+  if (patch.priority !== undefined) next.priority = patch.priority;
+  if (patch.status === 'done' && item.status !== 'answered') {
+    next.status = 'answered';
+    next.response = { done: true };
+    next.answeredAt = now;
+  } else if (patch.status === 'pending') {
+    next.status = 'pending';
+    delete next.response;
+    delete next.answeredAt;
+  }
+  return next;
+}
+
+/** Validation shared by the CLI and the MCP tool; returns an error message or null. */
+export function reminderPatchError(patch: ReminderPatch): string | null {
+  if (patch.text !== undefined && !patch.text.trim()) return 'le texte ne peut pas être vide';
+  if (typeof patch.dueAt === 'string' && Number.isNaN(Date.parse(patch.dueAt))) {
+    return `échéance invalide (date ISO attendue) : "${patch.dueAt}"`;
+  }
+  if (
+    patch.text === undefined &&
+    patch.dueAt === undefined &&
+    patch.priority === undefined &&
+    patch.status === undefined
+  ) {
+    return 'rien à modifier (texte, échéance, priorité ou statut attendu)';
+  }
+  return null;
+}
+
+export type UpdateReminderResult =
+  | { kind: 'not-found' }
+  | { kind: 'invalid'; error: string }
+  | { kind: 'unchanged'; item: ReminderItem }
+  | { kind: 'updated'; item: ReminderItem }
+  | { kind: 'error'; error: string };
+
+const UPDATE_MAX_ATTEMPTS = 3;
+
+/**
+ * Edit ONE reminder — the single write path of `remind update` and the MCP
+ * `remind_update` tool. The delta is re-checked by `isReminderEditOnlyFlip`
+ * before the write (only that item, only editable fields, status limited to
+ * the exact done/reopen shapes), then saved with the same bounded retry on
+ * an optimistic-lock conflict as `remind_add`: each attempt re-reads the
+ * evergreen conversation and re-applies the patch onto the fresh copy.
+ */
+export async function updateReminder(itemId: string, patch: ReminderPatch): Promise<UpdateReminderResult> {
+  const invalid = reminderPatchError(patch);
+  if (invalid) return { kind: 'invalid', error: invalid };
+
+  let lastConflict = 'raison inconnue';
+  for (let attempt = 1; attempt <= UPDATE_MAX_ATTEMPTS; attempt++) {
+    const found = await findReminderById(itemId);
+    if (!found) return { kind: 'not-found' };
+    const { conversation, item } = found;
+
+    const nextItem = applyReminderPatch(item, patch, new Date().toISOString());
+    if (JSON.stringify(nextItem) === JSON.stringify(item)) return { kind: 'unchanged', item };
+
+    const nextConversation: Conversation = {
+      ...conversation,
+      items: conversation.items.map((it) => (it.id === itemId ? nextItem : it)),
+    };
+    if (!isReminderEditOnlyFlip(conversation, nextConversation)) {
+      return {
+        kind: 'error',
+        error:
+          "identity guard: le delta construit pour l'édition ne se limite pas aux champs " +
+          'modifiables (texte, échéance, priorité, statut) d’un seul rappel — écriture refusée.',
+      };
+    }
+
+    const result = await saveConversation(REMINDERS_SLUG, REMINDERS_ID, nextConversation);
+    if (result.ok) {
+      const written = result.conversation.items.find(
+        (it): it is ReminderItem => it.kind === 'reminder' && it.id === itemId,
+      );
+      return { kind: 'updated', item: written ?? nextItem };
+    }
+    if ('conflict' in result && result.conflict) {
+      lastConflict = saveFailureReason(result);
+      continue;
+    }
+    if ('secretBlocked' in result) {
+      return { kind: 'error', error: 'le texte ressemble à une valeur de secret — un rappel ne doit jamais en contenir' };
+    }
+    return { kind: 'error', error: saveFailureReason(result) };
+  }
+  return { kind: 'error', error: `échec après ${UPDATE_MAX_ATTEMPTS} tentatives (conflit de verrou optimiste) — ${lastConflict}` };
+}

/**
 * reminderStore — thin read layer over the evergreen `_reminders/rappels`
 * conversation (see `server/cli/remind.ts` for the write path/CLI doctrine).
 *
 * SINGLE SOURCE OF TRUTH for "what are the pending reminders" so `remind list`
 * and the `triage scan` CLI share one predicate instead of two copies drifting
 * apart. A reminder IS a conversation item (`kind: 'reminder'`) — this module
 * adds no new storage, it only reads the same store `saveConversation`/
 * `getConversation` already serve.
 */
import { ITEM_KIND_LABELS, type Conversation, type ItemPriority, type ReminderItem } from '../../src/types/conversation';
import { root } from '../config';
import { getConversation, saveConversation, saveFailureReason } from './conversationStore';
import { resolveAgentOrigin, readGitBranch, createdByFromOrigin, mergeOrigin } from '../lib/agentOrigin';
import type { AgentOrigin, OriginSource } from '../../src/types/agentOrigin';
import { isReminderEditOnlyFlip, isReminderOriginOnlyFlip } from './identityGuard';

export const REMINDERS_SLUG = '_reminders';
export const REMINDERS_ID = 'rappels';

/** Reads the evergreen reminders conversation, or `null` if it doesn't exist yet. */
export async function getRemindersConversation(): Promise<Conversation | null> {
  return getConversation(REMINDERS_SLUG, REMINDERS_ID);
}

/**
 * Loads the evergreen `_reminders` conversation, or builds its skeleton when it
 * doesn't exist yet — SHARED by every writer of a reminder (`remind add` CLI,
 * the `remind_add` MCP tool), so the evergreen conversation's shape is defined
 * in exactly one place rather than copy-pasted per caller.
 *
 * `source` (D2/D3, chantier « provenance de session », lot 2) lets each
 * caller identify itself for the origin resolver — the `remind add` CLI
 * defaults to `'cli'`, the `remind_add` MCP tool passes `'mcp'`. Only used on
 * the very FIRST call (the skeleton branch); once the conversation exists on
 * disk, its origin was already stamped at creation time and this is a no-op.
 */
export async function loadOrInitRemindersConversation(
  source: OriginSource = 'cli',
): Promise<Conversation> {
  const existing = await getRemindersConversation();
  if (existing) return existing;

  const now = new Date().toISOString();
  const origin = resolveAgentOrigin({
    env: process.env,
    cwd: root(),
    source,
    git: readGitBranch,
    now,
  });
  return {
    schemaVersion: 1,
    id: REMINDERS_ID,
    project: {
      slug: REMINDERS_SLUG,
      name: 'Rappels',
      path: root(),
    },
    title: 'Rappels',
    summary:
      "Rappels accumulés au fil du temps, ajoutés depuis n'importe quel projet via `bun run remind add` ou l'outil MCP `remind_add`.",
    status: 'pending',
    items: [],
    createdAt: now,
    updatedAt: now,
    origin,
    createdBy: createdByFromOrigin(origin, undefined),
  };
}

/**
 * Deterministic-enough id for a fresh reminder item — SHARED by every writer
 * (see `loadOrInitRemindersConversation`), so the id shape lives in one place.
 */
export function newReminderItemId(): string {
  return `reminder-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * Build a fresh `ReminderItem` — SHARED by every writer that creates a
 * reminder (`remind add` CLI, the `remind_add` MCP tool) so the item's shape
 * (id, kind, title, prompt/body, context, `origin`) lives in exactly ONE
 * place rather than two independently-maintained copies (chantier
 * « provenance de session », lot 7 — the two call sites used to build this
 * object inline, byte-for-byte identically except for `origin`, which
 * neither of them stamped at all before this lot).
 *
 * `origin` is REQUIRED (not optional/defaulted here): every caller already
 * has a resolved `AgentOrigin` in hand (`resolveAgentOrigin({..., source:
 * 'cli' | 'mcp'})`) by the time it calls this — this function never resolves
 * one itself, so it stays a pure, trivially-testable builder.
 */
export function buildReminderItem(
  input: { text: string; dueAt?: string; priority?: ItemPriority; project?: string; context?: string },
  origin: AgentOrigin,
): ReminderItem {
  const text = input.text.trim();
  return {
    id: newReminderItemId(),
    kind: 'reminder',
    title: ITEM_KIND_LABELS.reminder,
    prompt: text,
    context: input.context ?? (input.project ? `Ajouté depuis le projet « ${input.project} ».` : undefined),
    body: text,
    status: 'pending',
    origin,
    ...(input.priority ? { priority: input.priority } : {}),
    ...(input.dueAt ? { dueAt: new Date(input.dueAt).toISOString() } : {}),
  };
}

/** All `reminder` items still `status: 'pending'`, in the order they were added. */
export async function listPendingReminders(): Promise<ReminderItem[]> {
  const conversation = await getRemindersConversation();
  return (
    conversation?.items.filter(
      (item): item is ReminderItem => item.kind === 'reminder' && item.status === 'pending',
    ) ?? []
  );

/* ---- reminder (note to self, dashboard-visible) --------------------------
 * Calqué sur `note`, mais un kind explicite et typé plutôt qu'une convention
 * de slug fragile pour distinguer « rappel » de « note d'acquittement
 * quelconque » d'un vrai projet. Compte TOUJOURS vers la complétion tant que
 * non répondu (comportement par défaut de itemCountsTowardCompletion, aucune
 * règle spéciale comme pour `note`).
 * -------------------------------------------------------------------------- */

export const ReminderResponseSchema = z.object({
  done: z.boolean(),
});

export const ReminderItemSchema = z.object({
  ...itemBaseShape,
  kind: z.literal('reminder'),
  /** Texte du rappel (Markdown). */
  body: z.string().min(1),
  response: ReminderResponseSchema.optional(),
  origin: AgentOriginSchema.optional(),
});

/* ---- discriminated union ------------------------------------------------- */

export const ItemSchema = z.discriminatedUnion('kind', [
  DecisionItemSchema,
  QuestionItemSchema,
  ApprovalItemSchema,
  ChecklistItemSchema,
  ProposalItemSchema,
  NoteItemSchema,
  RatingItemSchema,
  SecretRequestItemSchema,
  ReminderItemSchema,
]);

/* -------------------------------------------------------------------------- */
/*  Conversation                                                              */
/* -------------------------------------------------------------------------- */

export const ConversationProjectSchema = z.object({
  slug: z.string().min(1),
  name: z.string().min(1),
  path: z.string().optional(),
});

export const ConversationSchema = z.object({
  schemaVersion: z.literal(1),
  id: z.string().min(1),
  project: ConversationProjectSchema,
  title: z.string().min(1),
  summary: z.string().optional(),
  /** Id of the template this conversation was created from (documentation). */
  templateId: z.string().optional(),
  status: ConversationStatusSchema,
  items: z.array(ItemSchema),
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
  answeredAt: z.string().datetime().nullable().optional(),
  createdBy: z.enum(['claude', 'user', 'codex']).optional(),
  origin: AgentOriginSchema.optional(),

