import fs from 'node:fs/promises';
import path from 'node:path';

import {
  ExternalTaskSchema,
  type ExternalTask,
  type ExternalTaskMeta,
  type ExternalTaskSaveResult,
} from '../../src/types/task';
import { dataRoot, tasksDir } from '../config';
import { atomicWrite } from '../lib/atomicWrite';
import { isSafeSegment } from './slug';

/**
 * File-backed store for External Tasks, copied from chipStore's patron:
 * `data/tasks/<slug>/<id>.json`, zod as the single source of truth, atomic
 * writes, optimistic locking on `updatedAt`, soft-delete to `<dataRoot>/trash/tasks`.
 *
 * This store does NOT publish on the event bus — like chips, the disk watcher
 * (taskWatcher.ts, via createTreeWatcher) is the ONLY publisher of
 * 'tasks-changed', so every write path (UI edit, seed, or a manager patch)
 * gets the same live-update behavior for free.
 */

/* -------------------------------------------------------------------------- */
/*  Path resolution + guards                                                  */
/* -------------------------------------------------------------------------- */

function taskPath(slug: string, id: string): string {
  if (!isSafeSegment(slug) || !isSafeSegment(id)) {
    throw new Error('Invalid slug or id');
  }
  return path.join(tasksDir(), slug, `${id}.json`);
}

/**
 * A fresh `updatedAt` guaranteed STRICTLY LATER than `prevIso`. Two writes in
 * the same millisecond would otherwise stamp an identical `updatedAt`, which
 * silently defeats the optimistic lock (a stale save would match the on-disk
 * timestamp and slip through). Bumping to `prev + 1ms` when the wall clock has
 * not advanced keeps the lock reliable and preserves write ordering for the
 * watcher/UI.
 */
function nextUpdatedAt(prevIso: string): string {
  const prevMs = Date.parse(prevIso);
  const nowMs = Number.isNaN(prevMs) ? Date.now() : Math.max(Date.now(), prevMs + 1);
  return new Date(nowMs).toISOString();
}

async function readTaskFile(filePath: string): Promise<ExternalTask | null> {
  let raw: string;
  try {
    raw = await fs.readFile(filePath, 'utf8');
  } catch {
    return null;
  }
  try {
    const parsed = JSON.parse(raw);
    const result = ExternalTaskSchema.safeParse(parsed);
    return result.success ? result.data : null;
  } catch {
    return null;
  }
}

/** Every task under TASKS_DIR, optionally restricted to a single project slug. */
async function allTasks(slugFilter?: string): Promise<ExternalTask[]> {
  const base = tasksDir();
  let slugs: string[];
  try {
    const entries = await fs.readdir(base, { withFileTypes: true });
    slugs = entries.filter((d) => d.isDirectory()).map((d) => d.name);
  } catch {
    return [];
  }
  if (slugFilter) slugs = slugs.filter((s) => s === slugFilter);

  const tasks: ExternalTask[] = [];
  await Promise.all(
    slugs.map(async (slug) => {
      let files: string[];
      try {
        files = (await fs.readdir(path.join(base, slug))).filter((f) => f.endsWith('.json'));
      } catch {
        return;
      }
      await Promise.all(
        files.map(async (file) => {
          const task = await readTaskFile(path.join(base, slug, file));
          if (task) tasks.push(task);
        }),
      );
    }),
  );
  return tasks;
}

/** Locate a task by id across all project slugs (scan, like chipStore's
 *  findChipLocation). If a collision ever happens, the most recently updated
 *  match wins. */
async function findTaskLocation(id: string): Promise<{ slug: string; task: ExternalTask } | null> {
  if (!isSafeSegment(id)) return null;
  const base = tasksDir();
  let slugs: string[];
  try {
    const entries = await fs.readdir(base, { withFileTypes: true });
    slugs = entries.filter((d) => d.isDirectory()).map((d) => d.name);
  } catch {
    return null;
  }

  const matches: { slug: string; task: ExternalTask }[] = [];
  await Promise.all(
    slugs.map(async (slug) => {
      const task = await readTaskFile(path.join(base, slug, `${id}.json`));
      if (task) matches.push({ slug, task });
    }),
  );
  if (matches.length === 0) return null;
  matches.sort((a, b) => b.task.updatedAt.localeCompare(a.task.updatedAt));
  return matches[0];
}

/* -------------------------------------------------------------------------- */
/*  Metas                                                                     */
/* -------------------------------------------------------------------------- */

function toMeta(t: ExternalTask): ExternalTaskMeta {
  return {
    id: t.id,
    project: t.project,
    title: t.title,
    kind: t.kind,
    status: t.status,
    health: t.health,
    lastRunAt: t.lastRunAt,
    lastRunSuccess: t.lastRunSuccess,
    createdAt: t.createdAt,
    updatedAt: t.updatedAt,
  };
}

/** List task metas, optionally filtered to a project slug. Most recently
 *  updated first. */
export async function listTasks(filter?: { slug?: string }): Promise<ExternalTaskMeta[]> {
  const tasks = await allTasks(filter?.slug);
  const metas = tasks.map(toMeta);
  metas.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  return metas;
}

/* -------------------------------------------------------------------------- */
/*  Get one                                                                   */
/* -------------------------------------------------------------------------- */

export async function getTask(slug: string, id: string): Promise<ExternalTask | null> {
  return readTaskFile(taskPath(slug, id));
}

export async function findTask(id: string): Promise<ExternalTask | null> {
  const loc = await findTaskLocation(id);
  return loc ? loc.task : null;
}

/** Same as findTask but also returns the resolved slug — routes need it to
 *  build the on-disk path for a mutation without re-scanning. */
export async function findTaskWithSlug(
  id: string,
): Promise<{ slug: string; task: ExternalTask } | null> {
  return findTaskLocation(id);
}

/* -------------------------------------------------------------------------- */
/*  Create                                                                    */
/* -------------------------------------------------------------------------- */

/* -------------------------------------------------------------------------- */

/** Create a task from a full, already-validated ExternalTask-shaped object.
 *  Never overwrites an existing file at the same path — the caller (route,
 *  or taskSeed's idempotent bootstrap) is expected to check existence first
 *  if "don't clobber" matters; this function itself always writes. */
export async function createTask(input: unknown): Promise<ExternalTaskSaveResult> {
  const parsed = ExternalTaskSchema.safeParse(input);
  if (!parsed.success) {
    return { ok: false, error: parsed.error.format() };
  }
  const task = parsed.data;
  const filePath = taskPath(task.project.slug, task.id);
  await atomicWrite(filePath, JSON.stringify(task, null, 2));
  const persisted = await readTaskFile(filePath);
  if (!persisted) return { ok: false, error: 'Failed to re-read persisted task' };
  return { ok: true, task: persisted };
}

/** Whether a task file already exists at `<slug>/<id>.json` — used by
 *  taskSeed to stay idempotent (never overwrite an existing/edited task). */
export async function taskExists(slug: string, id: string): Promise<boolean> {
