export async function saveTask(
  slug: string,
  id: string,
  body: unknown,
): Promise<ExternalTaskSaveResult> {
  const parsed = ExternalTaskSchema.safeParse(body);
  if (!parsed.success) {
    return { ok: false, error: parsed.error.format() };
  }

  const incoming = parsed.data;
  if (incoming.id !== id || incoming.project.slug !== slug) {
    return { ok: false, error: 'id/slug in body must match URL' };
  }

  const filePath = taskPath(slug, id);
  const existing = await readTaskFile(filePath);
  if (!existing) {
    return { ok: false, error: 'Task not found' };
  }
  if (existing.updatedAt !== incoming.updatedAt) {
    return {
      ok: false,
      conflict: true,
      current: existing,
      error:
        'Le fichier a été modifié depuis son ouverture. Rechargez la page pour récupérer la dernière version.',
    };
  }

  const now = nextUpdatedAt(existing.updatedAt);
  const next: ExternalTask = ExternalTaskSchema.parse({ ...incoming, updatedAt: now });
  await atomicWrite(filePath, JSON.stringify(next, null, 2));

  const persisted = await readTaskFile(filePath);
  if (!persisted) return { ok: false, error: 'Failed to re-read persisted task' };
  return { ok: true, task: persisted };
}

