1	import type { ReactNode } from 'react';
2	
3	export interface SegmentedOption<V extends string> {
4	  value: V;
5	  label: string;
6	  icon?: ReactNode;
7	  /** Pastille numérique facultative (ex. nombre d'alertes). */
8	  badge?: number;
9	  /** Classes de la pastille (par défaut : teinte cuivre discrète). */
10	  badgeClassName?: string;
11	  title?: string;
12	}
13	
14	interface SegmentedControlProps<V extends string> {
15	  value: V;
16	  onChange: (value: V) => void;
17	  options: readonly SegmentedOption<V>[];
18	  ariaLabel: string;
19	  className?: string;
20	  /** Classes ajoutées à chaque segment (ex. `flex-1` pour remplir une ligne). */
21	  segmentClassName?: string;
22	  /** Masque le libellé sous `sm` (l'icône et `aria-label` restent). */
23	  compactLabels?: boolean;
24	  disabled?: boolean;
25	}
26	
27	/**
28	 * Contrôle segmenté du système « journal d'atelier » : la piste
29	 * `.glass-segmented` et ses segments `data-shape="segment"`, dont l'état
30	 * sélectionné est porté par `aria-pressed` (teinte cuivre, `glass.css`).
31	 * Chaque segment affiche TOUJOURS un libellé lisible — jamais une pastille
32	 * pleine sans texte — et garde un anneau `focus-visible`.
33	 */
34	export function SegmentedControl<V extends string>({
35	  value,
36	  onChange,
37	  options,
38	  ariaLabel,
39	  className = '',
40	  segmentClassName = '',
41	  compactLabels = false,
42	  disabled = false,
43	}: SegmentedControlProps<V>) {
44	  return (
45	    <div
46	      role="group"
47	      aria-label={ariaLabel}
48	      className={`glass-segmented !p-[3px] !gap-0.5 ${className}`}
49	    >
50	      {options.map((option) => {
51	        const active = option.value === value;
52	        return (
53	          <button
54	            key={option.value}
55	            type="button"
56	            data-shape="segment"
57	            data-size="xs"
58	            aria-pressed={active}
59	            aria-label={compactLabels ? option.label : undefined}
60	            title={option.title ?? (compactLabels ? option.label : undefined)}
61	            disabled={disabled}
62	            onClick={() => {
63	              if (!active) onChange(option.value);
64	            }}
65	            className={`glass-control h-7 min-w-0 gap-1.5 whitespace-nowrap !py-0 font-mono tracking-tight transition-[background-color,color,box-shadow] duration-200 ${
66	              active ? 'font-semibold' : 'text-ink-soft hover:text-ink hover:!bg-paper-deep/60'
67	            } disabled:opacity-50 ${segmentClassName}`}
68	          >
69	            {option.icon}
70	            <span className={compactLabels ? 'hidden sm:inline' : 'truncate'}>{option.label}</span>
71	            {option.badge !== undefined && (
72	              <span
73	                className={`inline-grid min-w-[1.125rem] place-items-center rounded-md px-1 text-[0.625rem] font-bold leading-[1.125rem] ${
74	                  option.badgeClassName ?? 'bg-accent-tint text-accent-deep'
75	                }`}
76	              >
77	                {option.badge}
78	              </span>
79	            )}
80	          </button>
81	        );
82	      })}
83	    </div>
84	  );
85	}
