87	interface ReminderEditorProps {
88	  /** Instantané du rappel à l'ouverture (base de la fusion à trois voies). */
89	  item: ReminderItem;
90	  saving: boolean;
91	  /** Message d'erreur serveur/réseau déjà traduit. */
92	  error: string | null;
93	  onSave: (draft: ReminderDraft) => void;
94	  onCancel: () => void;
95	}
96	
97	/**
98	 * Éditeur en ligne d'un rappel : texte, priorité, échéance (poser / changer /
99	 * effacer) et statut (en cours ↔ fait). Entrée enregistre, Maj+Entrée ajoute
100	 * une ligne, ⌘/Ctrl+Entrée enregistre partout, Échap annule.
101	 */
102	export function ReminderEditor({ item, saving, error, onSave, onCancel }: ReminderEditorProps) {
103	  const { t } = useTranslation();
104	  const [draft, setDraft] = useState<ReminderDraft>(() => draftFromReminder(item));
105	  const [showValidation, setShowValidation] = useState(false);
106	  const baseId = useId();
107	
108	  const validation = validateReminderDraft(draft);
109	  const dirty = isReminderDraftDirty(item, draft);
110	
111	  const update = <K extends keyof ReminderDraft>(key: K, value: ReminderDraft[K]) => {
112	    setDraft((prev) => ({ ...prev, [key]: value }));
113	  };
114	
115	  const submit = () => {
116	    if (saving) return;
117	    if (validation) {
118	      setShowValidation(true);
119	      return;
120	    }
121	    if (!dirty) {
122	      onCancel();
123	      return;
124	    }
125	    onSave(draft);
126	  };
127	
128	  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
129	    if (event.nativeEvent.isComposing) return;
130	    if (event.key === 'Escape') {
131	      event.preventDefault();
132	      event.stopPropagation();
133	      if (!saving) onCancel();
134	      return;
135	    }
136	    if (event.key !== 'Enter') return;
137	    const target = event.target as HTMLElement;
138	    const withModifier = event.metaKey || event.ctrlKey;
139	    // Sans modificateur, un bouton garde son comportement natif (Entrée = clic).
140	    if (!withModifier && target.tagName === 'BUTTON') return;
141	    // Maj+Entrée dans le texte = nouvelle ligne.
142	    if (!withModifier && target.tagName === 'TEXTAREA' && event.shiftKey) return;
143	    event.preventDefault();
144	    submit();
145	  };
146	
147	  const statusOptions: SegmentedOption<'pending' | 'done'>[] = [
148	    { value: 'pending', label: t('reminders.edit.statusPending'), icon: <CircleDashed aria-hidden /> },
149	    { value: 'done', label: t('reminders.edit.statusDone'), icon: <CircleCheck aria-hidden /> },
150	  ];
151	
152	  const validationMessage =
153	    showValidation && validation ? t(`reminders.edit.errors.${validation}`) : null;
154	  const message = validationMessage ?? error;
155	
156	  return (
157	    <div
158	      role="group"
159	      aria-label={t('reminders.edit.regionLabel')}
160	      aria-busy={saving}
161	      onKeyDown={handleKeyDown}
162	      className="rise flex flex-col gap-3 rounded-xl border border-accent/40 bg-paper-raised/90 p-3 shadow-warm-sm sm:p-4"
163	    >
164	      <Textarea
165	        id={`${baseId}-text`}
166	        label={t('reminders.edit.textLabel')}
167	        value={draft.text}
168	        rows={Math.min(6, Math.max(2, draft.text.split('\n').length))}
169	        disabled={saving}
170	        autoFocus
171	        onFocus={(event) => {
172	          const end = event.currentTarget.value.length;
173	          event.currentTarget.setSelectionRange(end, end);
174	        }}
175	        onChange={(event) => update('text', event.target.value)}
176	        aria-invalid={showValidation && validation === 'emptyText'}
177	      />
178	
179	      <div className="flex flex-wrap items-end gap-x-4 gap-y-3">
180	        <div className="flex min-w-0 flex-col gap-1.5">
181	          <span className="eyebrow text-ink-faint" aria-hidden>
182	            {t('reminders.edit.priorityLabel')}
183	          </span>
184	          <ReminderPrioritySegmented
185	            value={draft.priority}
186	            onChange={(value) => update('priority', value)}
187	            disabled={saving}
188	          />
189	        </div>
190	
191	        <div className="flex min-w-0 flex-col gap-1.5">
192	          <label className="eyebrow text-ink-faint" htmlFor={`${baseId}-due`}>
193	            {t('reminders.edit.dueLabel')}
194	          </label>
195	          <ReminderDueInput
196	            id={`${baseId}-due`}
197	            value={draft.dueAt}
198	            onChange={(value) => update('dueAt', value)}
199	            disabled={saving}
200	          />
201	        </div>
202	
203	        <div className="flex min-w-0 flex-col gap-1.5">
204	          <span className="eyebrow text-ink-faint" aria-hidden>
205	            {t('reminders.edit.statusLabel')}
206	          </span>
207	          <SegmentedControl
208	            ariaLabel={t('reminders.edit.statusLabel')}
209	            value={draft.done ? 'done' : 'pending'}
210	            onChange={(value) => update('done', value === 'done')}
211	            options={statusOptions}
212	            disabled={saving}
213	          />
214	        </div>
215	      </div>
216	
217	      {message && (
218	        <p
219	          role="alert"
220	          className="rounded-lg border border-accent/30 bg-accent/10 px-3 py-2 text-xs text-accent-deep"
221	        >
222	          {message}
223	        </p>
224	      )}
225	
226	      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-line-soft/60 pt-3">
227	        <p className="min-w-0 font-mono text-[0.6875rem] leading-snug text-ink-faint">
228	          {t('reminders.edit.hint')}
229	        </p>
230	        <div className="flex shrink-0 items-center gap-2">
231	          <Button type="button" variant="ghost" size="sm" onClick={onCancel} disabled={saving}>
232	            {t('common.cancel')}
233	          </Button>
234	          <Button type="button" variant="accent" size="sm" onClick={submit} loading={saving}>
235	            {!saving && <Save className="h-3.5 w-3.5" aria-hidden />}
236	            {t('reminders.edit.save')}
237	          </Button>
238	        </div>
239	      </div>
240	    </div>
241	  );
242	}
