/** Top-level directories of this macOS machine (and the usual Unix ones). */
const LOCAL_ROOTS =
  'Users|home|private|var|tmp|Volumes|opt|root|Applications|Library|System|etc|usr|bin|sbin|cores|dev|mnt|Network';

/** Root + at least one segment (`/tmp` or `~` alone reveals nothing and may be
 *  a word — left alone), optionally as a `file://` URL. Case-insensitive: the
 *  macOS disk is (`/users/…` is the same directory). */
const PATH_HEAD = `(?:file://)?(?:~|/(?:${LOCAL_ROOTS}))/`;

/** A string that IS a local absolute path — whole string, spaces allowed
 *  (`/Applications/Visual Studio Code.app`), not a path mentioned inside a
 *  sentence. Tested on the trimmed value. */
const LOCAL_ABSOLUTE_PATH = new RegExp(`^${PATH_HEAD}[^\\n]+$`, 'i');

/** Error text is cut to this length before any regex runs: an error can echo
 *  caller input (an invalid 5 MB slug), and the redaction must stay linear. */
const MAX_ERROR_TEXT = 2000;

/** Inside a text: a QUOTED path, redacted whole even with spaces
 *  (`mkdir '/Users/x/My Projets/data'`) — Node fs errors quote their paths.
 *  The closing quote must END the token (end of text, whitespace or
 *  punctuation), so a quote INSIDE the path (`…/O'Brien's Data/sub'`) does not
 *  cut it short. Bounded to 1024 chars (PATH_MAX) so a quote-heavy input
 *  cannot make it backtrack quadratically. */
const QUOTED_LOCAL_PATH = new RegExp(
  `(['"\`])(${PATH_HEAD}[^\\n]{0,1024}?)\\1(?=$|[\\s,;:.!?)\\]}>])`,
  'gi',
);

/** Inside a text: a BARE path token, which must start the text or follow a
 *  space, a quote, a bracket or a separator — never a segment inside a URL
 *  (`https://host/Users/42` stays intact). Covers JSON-serialized errors
 *  (`{"path":"/Users/…"}`) and unterminated quotes. Stops at whitespace,
 *  quotes and closing brackets. */
const BARE_LOCAL_PATH = new RegExp(`(?<=^|[\\s(\\[{=:,;|'"\`«>])${PATH_HEAD}[^\\s'"\`)\\]}»]*`, 'gi');

export function isLocalAbsolutePath(value: string): boolean {
  return LOCAL_ABSOLUTE_PATH.test(value.trim());

